// spec: specs/business-cards-images.md (3.1) · кейс: .qa/tests/businessdetail-gallery/GALLERY-17
// #494e0b поверх #d31f3b: в галерее объявления файл — оригинал (постер ≈738×1600 с чёрными полями сверху/снизу),
// окно — cover 16:9 по центру, поэтому чёрные поля оригинала уходят за рамку. Проверяем, что в ВИДИМОЙ области
// (часть оригинала, которую показывает cover при object-position 50% 50%) нет чёрных строк.
// seed: tests/seed.spec.ts (гость) · прод, только просмотр: не-GET блокируются, cookie/PWA заранее, SW выключен.
import { test, expect } from '@playwright/test';
import { prepare, openListing, settledImage, expectCovered, expectFixedFrame } from './gallery.helpers';
import { DARK, darkRowCount, measureLines, short } from '../business-cards-images/trim.helpers';

test.use({ serviceWorkers: 'block' });

/** «מסעדה וגן אירועים» — первая картинка галереи: постер 738×1600 с чёрными полями (замер QA 2026-11-19). */
const POSTER_ID = 'e8204967-0da2-4807-9f98-c1330c7e30b4';

test.describe('Галерея страницы объявления — постер с полями (#494e0b)', () => {
  test.beforeEach(async ({ page }) => {
    await prepare(page);
  });

  test('первая картинка постера в рамке cover 16:9 без чёрного #494e0b #d31f3b @mobile @prod-safe', async ({ page }) => {
    await openListing(page, POSTER_ID);
    const s = await settledImage(page, 'картинка 1');
    const img = s.img!;
    test.info().annotations.push({
      type: 'замер',
      description: `${short(img.src)} ${img.nat.join('×')}, рамка ${s.win.w.toFixed(1)}×${s.win.h.toFixed(1)}, fit ${img.fit} ${img.pos}`,
    });

    // Рамка 16:9 (±2 %) во всю ширину, img = рамке ±1 px, cover по центру (#d31f3b).
    expectFixedFrame(s, '@mobile', 'картинка 1');
    expectCovered(s, 'картинка 1');

    // Видимая часть оригинала при cover 50% 50%: масштаб = max(W/nw, H/nh), по центру.
    const [nw, nh] = img.nat;
    const k = Math.max(s.win.w / nw, s.win.h / nh);
    const sw = Math.min(nw, s.win.w / k);
    const sh = Math.min(nh, s.win.h / k);
    const region = { sx: (nw - sw) / 2, sy: (nh - sh) / 2, sw, sh };
    const l = await measureLines(page, img.src, region);
    const dark = darkRowCount(l);
    const minRow = Math.min(...l.rowMean);
    test.info().annotations.push({
      type: 'видимая область',
      description: `исходник ${l.w}×${l.h}, видно x ${region.sx.toFixed(0)}..${(region.sx + sw).toFixed(0)}, y ${region.sy.toFixed(0)}..${(region.sy + sh).toFixed(0)}; строк ${l.rowMean.length}, тёмных (< ${DARK}) ${dark}, мин. яркость строки ${minRow.toFixed(1)}`,
    });
    expect(dark, `в видимой области рамки нет чёрных строк (средняя < ${DARK}); мин. ${minRow.toFixed(1)}`).toBe(0);
  });
});
